use std::io::{self, BufRead, Write};

#[derive(Clone, Copy)]
struct Span {
    start: usize,
    end: usize,
    present: bool,
}

impl Span {
    const EMPTY: Self = Self { start: 0, end: 0, present: false };

    fn from_line(line: &str) -> Self {
        let mut result = Self::EMPTY;
        for (index, ch) in line.char_indices() {
            if !ch.is_whitespace() {
                if !result.present {
                    result.start = index;
                    result.present = true;
                }
                result.end = index;
            }
        }
        result
    }

    fn merge(&mut self, other: Self) {
        if !other.present { return; }
        if !self.present {
            *self = other;
        } else {
            self.start = self.start.min(other.start);
            self.end = self.end.max(other.end);
        }
    }
}

fn draw<W: Write>(rows: &[Span], scale: f64, padding: usize, out: &mut W) -> io::Result<()> {
    let last = rows.iter().map(|r| r.end).max().unwrap_or(0);
    let dot_width = ((last + 1) as f64 * scale) as usize;
    let width = dot_width / 2 + dot_width % 2;
    let mut cells = vec![0u8; width];
    const DOTS: [[u8; 2]; 4] = [[1, 8], [2, 16], [4, 32], [64, 128]];
    for (y, span) in rows.iter().enumerate() {
        if !span.present { continue; }
        let left = (span.start as f64 * scale) as usize;
        let right = ((span.end + 1) as f64 * scale) as usize;
        for x in left..right {
            cells[x / 2] |= DOTS[y][x % 2];
        }
    }
    let mut buffer = Vec::with_capacity(width.saturating_mul(3).saturating_add(1));
    for cell in cells {
        let code = 0x2800u32 + cell as u32;
        buffer.push((0xe0 | (code >> 12)) as u8);
        buffer.push((0x80 | ((code >> 6) & 0x3f)) as u8);
        buffer.push((0x80 | (code & 0x3f)) as u8);
    }
    if padding > width {
        buffer.resize(buffer.len() + padding - width, b' ');
    }
    buffer.push(b'\n');
    out.write_all(&buffer)
}

pub fn render<R: BufRead, W: Write>(mut input: R, mut output: W, hscale: f64,
                                     vscale: f64, padding: usize, strict: bool) -> io::Result<()> {
    let mut data = Vec::new();
    let mut rows = [Span::EMPTY; 4];
    let mut row_count = 0usize;
    let mut merged = Span::EMPTY;
    let mut pending = false;
    let mut current_key = 0usize;
    let mut line_index = 0usize;
    loop {
        data.clear();
        let count = input.read_until(b'\n', &mut data)?;
        if count == 0 { break; }
        let text = if strict {
            std::borrow::Cow::Borrowed(std::str::from_utf8(&data)
                .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8"))?)
        } else {
            String::from_utf8_lossy(&data)
        };
        let span = Span::from_line(&text);
        let key = (line_index as f64 * vscale) as usize;
        if pending && key != current_key {
            rows[row_count] = merged;
            row_count += 1;
            if row_count == 4 {
                draw(&rows, hscale, padding, &mut output)?;
                rows = [Span::EMPTY; 4];
                row_count = 0;
            }
            merged = Span::EMPTY;
        }
        current_key = key;
        pending = true;
        merged.merge(span);
        line_index += 1;
        // A look-ahead key closes groups immediately, so completed cells are
        // retained even if the following input line is invalid UTF-8.
        let next_key = (line_index as f64 * vscale) as usize;
        if next_key != current_key {
            rows[row_count] = merged;
            row_count += 1;
            if row_count == 4 {
                draw(&rows, hscale, padding, &mut output)?;
                rows = [Span::EMPTY; 4];
                row_count = 0;
            }
            merged = Span::EMPTY;
            pending = false;
        }
    }
    if pending {
        rows[row_count] = merged;
        row_count += 1;
    }
    if row_count != 0 {
        draw(&rows[..row_count], hscale, padding, &mut output)?;
    }
    output.flush()
}
EOF"}

