mod cli;
mod completion;
mod render;

use std::io::{self, BufReader, Write};
use std::path::Path;
use std::fs::File;

fn execute(action: cli::Action) -> io::Result<()> {
    let stdout = io::stdout();
    let mut output = stdout.lock();
    match action {
        cli::Action::Text(text) => output.write_all(text.as_bytes()),
        cli::Action::Completion(shell) => output.write_all(completion::generate(&shell).as_bytes()),
        cli::Action::Render(config) => {
            if let Some(path) = config.file {
                render::render(BufReader::new(File::open(path)?), &mut output,
                    config.horizontal, config.vertical, config.padding, config.strict)
            } else {
                let stdin = io::stdin();
                render::render(stdin.lock(), &mut output,
                    config.horizontal, config.vertical, config.padding, config.strict)
            }
        }
    }
}

fn main() {
    let args: Vec<_> = std::env::args_os().collect();
    let program = args.first().and_then(|p| Path::new(p).file_name())
        .map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "executable".to_string());
    let action = match cli::parse(&program, &args[1..]) {
        Ok(action) => action,
        Err(error) => {
            let _ = io::stderr().write_all(error.as_bytes());
            std::process::exit(2);
        }
    };
    if let Err(error) = execute(action) {
        let _ = writeln!(io::stderr(), "code-minimap: {error}");
        std::process::exit(1);
    }
}
EOF"}

