fn fish() -> String {
    let mut s = String::from(r#"# Print an optspec for argparse to handle cmd's options that are independent of any subcommand.
function __fish_code_minimap_global_optspecs
	string join \n H/horizontal-scale= V/vertical-scale= padding= encoding= version h/help
end

function __fish_code_minimap_needs_command
	# Figure out if the current invocation already has a command.
	set -l cmd (commandline -opc)
	set -e cmd[1]
	argparse -s (__fish_code_minimap_global_optspecs) -- $cmd 2>/dev/null
	or return
	if set -q argv[1]
		# Also print the command, so this can be used to figure out what it is.
		echo $argv[1]
		return 1
	end
	return 0
end

function __fish_code_minimap_using_subcommand
	set -l cmd (__fish_code_minimap_needs_command)
	test -z "$cmd"
	and return 1
	contains -- $cmd[1] $argv
end

"#);
    for path in ["", "completion", "help"] {
        let cond = if path.is_empty() {
            "__fish_code_minimap_needs_command".to_string()
        } else { format!("__fish_code_minimap_using_subcommand {path}") };
        for opt in options(path) {
            let _ = write!(s, "complete -c code-minimap -n \"{cond}\"");
            if let Some(c) = opt.short { let _ = write!(s, " -s {c}"); }
            let _ = write!(s, " -l {} -d '{}'", opt.long, opt.description);
            if opt.value.is_some() { s.push_str(" -r"); }
            if opt.long == "encoding" { s.push_str(r#" -f -a "{utf8-lossy\t'',utf8\t''}""#); }
            s.push('\n');
        }
        for (cmd, desc) in commands(path) {
            if path == "help" {
                let _ = writeln!(s, "complete -c code-minimap -n \"{cond}; and not __fish_seen_subcommand_from completion help\" -f -a \"{cmd}\" -d '{desc}'");
            } else {
                let _ = writeln!(s, "complete -c code-minimap -n \"{cond}\" -a \"{cmd}\" -d '{desc}'");
            }
        }
    }
