}

fn zsh_options(s: &mut String, path: &str) {
    for opt in options(path) {
        let mut flags = Vec::new();
        if let Some(c) = opt.short {
            flags.push(format!("-{c}{}", if opt.value.is_some() { "+" } else { "" }));
        }
        flags.push(format!("--{}{}", opt.long, if opt.value.is_some() { "=" } else { "" }));
        for flag in flags {
            let _ = write!(s, "'{flag}[{}]", opt.description);
            if let Some(value) = opt.value {
                let values = if opt.long == "encoding" { "(utf8-lossy utf8)" } else { "_default" };
                let _ = write!(s, ":{value}:{values}");
            }
            s.push_str("' \\\n");
        }
    }
}

