//! Formatting for help and diagnostics.  Rendering the minimap is deliberately
//! independent of these terminal settings.
use std::io::{self, IsTerminal};

const RESET: &str = "\x1b[0m";
const LITERAL: &str = "\x1b[1m\x1b[32m";
const HEADER: &str = "\x1b[1m\x1b[33m";
const PLACEHOLDER: &str = "\x1b[36m";
const VALID: &str = "\x1b[32m";
const INVALID: &str = "\x1b[33m";
const ERROR: &str = "\x1b[1m\x1b[31m";

pub fn use_color(stderr: bool) -> bool {
    let nonempty = |key: &str| std::env::var_os(key).is_some_and(|s| !s.is_empty());
    if nonempty("NO_COLOR") { return false; }
    if nonempty("CLICOLOR_FORCE") { return true; }
    if std::env::var_os("CLICOLOR").as_deref() == Some(std::ffi::OsStr::new("0")) { return false; }
    if std::env::var_os("TERM").as_deref() == Some(std::ffi::OsStr::new("dumb")) { return false; }
    if stderr { io::stderr().is_terminal() } else { io::stdout().is_terminal() }
}

fn terminal_width() -> Option<usize> {
    if let Ok(width) = std::env::var("COLUMNS") {
        if let Ok(width) = width.parse::<usize>() { return Some(width); }
    }
    #[cfg(target_os = "linux")]
    {
        #[repr(C)]
        struct Window { rows: u16, cols: u16, x: u16, y: u16 }
        unsafe extern "C" { fn ioctl(fd: i32, request: usize, ...) -> i32; }
        for fd in [1, 2, 0] {
            let mut size = Window { rows: 0, cols: 0, x: 0, y: 0 };
            if unsafe { ioctl(fd, 0x5413, &mut size) } == 0 && size.cols != 0 {
                return Some(size.cols as usize);
            }
        }
    }
    None
}

fn color(text: &str, style: &str) -> String {
    format!("{style}{text}{RESET}")
}

fn wrap(text: &str, indent: usize, width: usize) -> String {
    let available = width.saturating_sub(indent);
    let prefix = " ".repeat(indent);
    let mut result = prefix.clone();
    let mut length = 0;
    for word in text.split(' ') {
        if word.is_empty() { continue; }
        if length != 0 {
            if length.saturating_add(word.len()).saturating_add(1) <= available {
                result.push(' ');
                length += 1;
            } else {
                result.push('\n');
                result.push_str(&prefix);
                length = 0;
            }
        }
        result.push_str(word);
        length += word.len();
    }
    result
}

fn usage(text: &str, prog: &str) -> String {
    let mut rest = text.strip_prefix("Usage: ").unwrap_or(text);
    let mut result = color("Usage:", HEADER);
    result.push(' ');
    if let Some(after) = rest.strip_prefix(prog) {
        rest = after;
        let mut literal = prog.to_owned();
        for subcommand in [" completion", " help"] {
            if rest.starts_with(subcommand) {
                literal.push_str(subcommand);
                rest = &rest[subcommand.len()..];
                break;
            }
        }
        result.push_str(&color(&literal, LITERAL));
    }
    while !rest.is_empty() {
        if let Some(next) = rest.strip_prefix(' ') {
            result.push(' ');
